3. Test the function with various key presses to ensure it behaves as expected.

### Implementation

```typescript
// src/input.ts

// State to keep track of pressed keys
const pressedKeys = new Set<string>();

// Add event listeners for keydown and keyup
window.addEventListener('keydown', (event) => {
  pressedKeys.add(event.key);
});

window.addEventListener('keyup', (event) => {
  pressedKeys.delete(event.key);
});

// Exported function to check if a key is pressed
export function getKeyDown(key: string): boolean {
  return pressedKeys.has(key);
}
```

