// src/storage.ts

import * as fs from 'fs';
import * as path from 'path';

const CARDS_FILE_PATH = path.join(__dirname, 'cards.json');

export function loadCards(): Card[] {
    try {
        const data = fs.readFileSync(CARDS_FILE_PATH, 'utf-8');
        return JSON.parse(data);
    } catch (error) {
        if (error.code === 'ENOENT') {
            // File does not exist, return an empty array
            return [];
        }
        throw new Error(`Failed to load cards: ${error.message}`);
    }
}

export function saveCards(cards: Card[]): void {
    try {
        const data = JSON.stringify(cards, null, 2);
        fs.writeFileSync(CARDS_FILE_PATH, data);
    } catch (error) {
        throw new Error(`Failed to save cards: ${error.message}`);
    }
}

