// src/services/noteService.ts

import { Note } from '../models/noteModel';
import { NoteInput } from '../types/noteTypes';

// Mock database operations for demonstration purposes
const notes: Note[] = [];

export const createNote = async (noteInput: NoteInput): Promise<Note> => {
  if (!noteInput.title || !noteInput.content) {
    throw new Error('Title and content are required');
  }

  const newNote: Note = {
    id: Date.now().toString(),
    title: noteInput.title,
    content: noteInput.content,
    createdAt: new Date(),
    updatedAt: new Date(),
  };

  notes.push(newNote);
  return newNote;
};

export const getNotes = async (): Promise<Note[]> => {
  return notes;
};

export const updateNote = async (noteId: string, noteInput: NoteInput): Promise<Note> => {
  const noteIndex = notes.findIndex(note => note.id === noteId);
  if (noteIndex === -1) {
    throw new Error('Note not found');
  }

  if (!noteInput.title || !noteInput.content) {
    throw new Error('Title and content are required');
  }

  const updatedNote: Note = {
    ...notes[noteIndex],
    title: noteInput.title,
    content: noteInput.content,
    updatedAt: new Date(),
  };

  notes[noteIndex] = updatedNote;
  return updatedNote;
};

export const deleteNote = async (noteId: string): Promise<void> => {
  const noteIndex = notes.findIndex(note => note.id === noteId);
  if (noteIndex === -1) {
    throw new Error('Note not found');
  }

  notes.splice(noteIndex, 1);
};
```

