// client/src/api/notes.ts

// Import necessary modules and types
import axios from 'axios';
import { Note } from '../types';

// Define the base URL for the API
const API_BASE_URL = 'http://localhost:3000/api/notes';

// Fetch all notes
export const fetchNotes = async (): Promise<Note[]> => {
  try {
    const response = await axios.get<Note[]>(API_BASE_URL);
    return response.data;
  } catch (error) {
    console.error('Error fetching notes:', error);
    throw error;
  }
};

// Add a new note
export const addNote = async (note: Note): Promise<Note> => {
  try {
    const response = await axios.post<Note>(API_BASE_URL, note);
    return response.data;
  } catch (error) {
    console.error('Error adding note:', error);
    throw error;
  }
};

// Update an existing note
export const updateNote = async (noteId: string, updatedNote: Note): Promise<Note> => {
  try {
    const response = await axios.put<Note>(`${API_BASE_URL}/${noteId}`, updatedNote);
    return response.data;
  } catch (error) {
    console.error('Error updating note:', error);
    throw error;
  }
};

// Delete a note
export const deleteNote = async (noteId: string): Promise<void> => {
  try {
    await axios.delete(`${API_BASE_URL}/${noteId}`);
  } catch (error) {
    console.error('Error deleting note:', error);
    throw error;
  }
};
```

