// Note Interface
export interface Note {
  id: string;
  title: string;
  content: string;
  createdAt: Date;
  updatedAt: Date;
}

// NotesService Class
class NotesService {
  private storage: NoteStorage;

  constructor(storage: NoteStorage) {
    this.storage = storage;
  }

  async createNote(note: Omit<Note, 'id' | 'createdAt' | 'updatedAt'>): Promise<Note> {
    const newNote: Note = {
      ...note,
      id: Date.now().toString(),
      createdAt: new Date(),
      updatedAt: new Date(),
    };
    await this.storage.saveNote(newNote);
    return newNote;
  }

