    if (!note) return null;

    const updatedNote: Note = {
      ...note,
      ...update,
      updatedAt: new Date(),
    };
    await this.storage.updateNote(updatedNote);
    return updatedNote;
  }

  async deleteNote(id: string): Promise<boolean> {
    return this.storage.deleteNote(id);
  }
}

