// Define the Meeting type
type Meeting = {
  id: string;
  startTime: Date;
  endTime: Date;
};

// Internal state to store meetings
let meetings: Meeting[] = [];

// Function to add a meeting
export function addMeeting(newMeeting: Meeting): boolean {
  if (checkOverlap(newMeeting)) {
    return false; // Meeting overlaps, cannot add
  }
  meetings.push(newMeeting);
  return true; // Meeting added successfully
}

// Function to list all meetings
export function listMeetings(): Meeting[] {
  return meetings;
}

// Function to check for overlap
export function checkOverlap(newMeeting: Meeting): boolean {
  for (const meeting of meetings) {
    if (
      newMeeting.startTime < meeting.endTime &&
      newMeeting.endTime > meeting.startTime
    ) {
      return true; // Overlap detected
    }
  }
  return false; // No overlap
}
