import { convertTemperature } from './converter';

function main() {
    const readline = require('readline').createInterface({
        input: process.stdin,
        output: process.stdout
    });

    readline.question('Enter temperature value: ', (temperatureInput) => {
        readline.question('Enter unit (C for Celsius, F for Fahrenheit): ', (unitInput) => {
            const temperature = parseFloat(temperatureInput);
            const unit = unitInput.toUpperCase();

            if (isNaN(temperature) || (unit !== 'C' && unit !== 'F')) {
                console.error('Invalid input. Please enter a valid temperature and unit.');
                readline.close();
                return;
            }

            const convertedTemperature = convertTemperature(temperature, unit);
            console.log(`Converted Temperature: ${convertedTemperature}°${unit === 'C' ? 'F' : 'C'}`);
            readline.close();
        });
    });
}

main();
```

