```typescript
export function convertTemperature(temperature: number, unit: 'C' | 'F'): number {
    if (unit === 'C') {
        return (temperature * 9/5) + 32; // Celsius to Fahrenheit
    } else if (unit === 'F') {
        return (temperature - 32) * 5/9; // Fahrenheit to Celsius
    } else {
        throw new Error('Invalid unit. Please use "C" for Celsius or "F" for Fahrenheit.');
    }
}
```

